/* Defining a Mixin */
.button-styles(@bg-color, @text-color) {
   background-color: @bg-color;
   color: @text-color;
   padding: 10px 20px;
   border: none;
   border-radius: 5px;
   cursor: pointer;
}

/* Using the Mixin */
.button {
   .button-styles(blue, white);
}

.button-secondary {
   .button-styles(gray, black);
}

html {
   font-size: 16px; /* Root font size */
}
.container {
   font-size: 1.5rem; /* 1.5 * 16px = 24px */
}
.child {
   font-size: 2rem; /* 2 * 16px = 32px */
}

input[type]{
   border: 1px solid black;
}

a[href="https://www.google.com"]{
   color: blue;
}

/* Descendant */
div p {
   color: red;  /* All <p> inside <div> will be red */
}

/* Child */
div > p {
   color: blue;  /* Only the direct <p> children of <div> will be blue */
}

/* Adjacent Sibling */
h1 + p {
   color: green;  /* The first <p> immediately following <h1> will be green */
}

/* General Sibling */
h1 ~ p {
   color: purple;  /* All <p> elements after <h1> will be purple */
}

element {
   float: none | left | right | initial | inherit;
}

/* Default styles for all devices */
body {
   font-size: 16px;
}

/* For tablets and smaller devices (max-width: 768px) */
@media (max-width: 768px) {
   body {
       font-size: 14px;
   }
}

/* For mobile devices (max-width: 480px) */
@media (max-width: 480px) {
   body {
       font-size: 12px;
   }
}

.myBgImage {
   background-image: url("image.jpg");
   background-size: cover; /* Scales and crops to fit the container */
   background-position: center; /* Centers the image */
   width: 100%;
   height: 300px;
}

img {
   width: 100%;
   height: auto;
}

@media (min-width: 768px) {
   img {
       width: 50%;
   }
}

body{
   display: flex;
   justify-content: center;
   align-items: center;
   height: 100vh;
}

.myDiv{
   width: 100px;
   height: 100px;
   background-color: red;
}

body{
   position: relative;
   height: 100vh;
}

.myDiv{
   width: 100px;
   height: 100px;
   background-color: red;

   position: absolute;
   left: 50%;
   top: 50%;
}

.icon {
   width: 32px;  /* Width of each icon */
   height: 32px; /* Height of each icon */
   background-image: url('sprite.png'); /* The sprite image */
   background-repeat: no-repeat;
}

.home {
   background-position: 0 0;  /* Position of the home icon in the sprite */
}

.search {
   background-position: -32px 0;  /* Position of the search icon */
}

.settings {
   background-position: -64px 0;  /* Position of the settings icon */
}
